// v3.3 BUGFIX: iterate ALL trigger items. The Asana trigger delivers multiple
// events per webhook batch (e.g., story:assigned + task added to section in
// the same execution). The default n8n Code node mode runs once with $json =
// FIRST item — so we were silently missing any QA move that wasn't the first
// item in the batch.
const QA_SECTION_GID = '1209047939293885';
const out = [];
for (const it of $input.all()) {
  const event = it.json;
  const triggerUserGid = (event.user && event.user.gid) || null;
  const eventCreatedAt = event.created_at || null;

  // Shape A — direct task→section add
  if (event.action === 'added' &&
      event.resource && event.resource.resource_type === 'task' &&
      event.parent && event.parent.resource_type === 'section' &&
      event.parent.gid === QA_SECTION_GID) {
    out.push({ json: { taskGid: event.resource.gid, source: 'direct_add',
                       qaSectionGid: QA_SECTION_GID, triggerUserGid, eventCreatedAt } });
    continue;
  }
  // Shape B — section_changed story
  if (event.action === 'added' &&
      event.resource && event.resource.resource_type === 'story' &&
      event.resource.resource_subtype === 'section_changed' &&
      event.parent && event.parent.resource_type === 'task') {
    out.push({ json: { taskGid: event.parent.gid, source: 'section_changed_story',
                       qaSectionGid: QA_SECTION_GID, triggerUserGid, eventCreatedAt } });
  }
}

// Dedupe on taskGid in case Shape A AND Shape B both fired for the same task
// (we'd otherwise do the downstream HTTP fetches twice).
const seen = new Set();
return out.filter(x => {
  const g = x.json.taskGid;
  if (seen.has(g)) return false;
  seen.add(g);
  return true;
});

// v3.3: as v3.2 (Entered QA At stamping), plus defensive checks for the case
// where Get Stories returned an Asana error body (rare — only happens if the
// task is deleted between Get Task succeeding and Get Stories running).
const QA_SECTION_GID = '1209047939293885';
const QA_CAME_FROM_FIELD_GID = '1214876159436964';
const ENTERED_QA_AT_FIELD_GID = '1215085559448866';

const storiesResp = $json;
if (storiesResp && Array.isArray(storiesResp.errors)) { return []; }
const stories = (storiesResp && storiesResp.data) ? storiesResp.data : (storiesResp.stories || []);

const taskResp = $('Asana: Get Task').first().json;
if (taskResp && Array.isArray(taskResp.errors)) { return []; }
const task = (taskResp && taskResp.data) ? taskResp.data : taskResp;
if (!task || !task.gid) { return []; }

const upstream = $('Filter: only QA section moves').first().json;
const triggerUserGid = upstream.triggerUserGid || null;

const inQA = (task.memberships || []).some(m => m && m.section && m.section.gid === QA_SECTION_GID);
if (!inQA) { return []; }

const qaMoveStories = stories
  .filter(s => s && s.resource_subtype === 'section_changed' && s.new_section && s.new_section.gid === QA_SECTION_GID)
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
const tMove = qaMoveStories.length ? new Date(qaMoveStories[0].created_at) : null;
const tMoveIso = tMove ? tMove.toISOString() : null;

let preMoveAssignee = null;
let derivedFrom = 'none';
let intentionallyUnassigned = false;
if (tMove) {
  const assignmentEvents = stories
    .filter(s => s && (s.resource_subtype === 'assigned' || s.resource_subtype === 'unassigned'))
    .filter(s => new Date(s.created_at) <= tMove)
    .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
  if (assignmentEvents.length) {
    const last = assignmentEvents[assignmentEvents.length - 1];
    if (last.resource_subtype === 'assigned' && last.assignee && last.assignee.gid) {
      preMoveAssignee = last.assignee;
      derivedFrom = 'story.assigned';
    } else if (last.resource_subtype === 'unassigned') {
      intentionallyUnassigned = true;
    }
  }
}
if (!preMoveAssignee && !intentionallyUnassigned && task.assignee && task.assignee.gid) {
  preMoveAssignee = task.assignee;
  derivedFrom = 'task.assignee (current)';
}
if (!preMoveAssignee && !intentionallyUnassigned && triggerUserGid) {
  preMoveAssignee = { gid: triggerUserGid, name: '(trigger user)' };
  derivedFrom = 'trigger.user (last resort)';
}
if (!preMoveAssignee) { return []; }

const existingPerson = (task.custom_fields || []).find(f => f && f.gid === QA_CAME_FROM_FIELD_GID);
const personMatches = existingPerson && existingPerson.people_value &&
                      existingPerson.people_value.length === 1 &&
                      existingPerson.people_value[0].gid === preMoveAssignee.gid;
const existingDate = (task.custom_fields || []).find(f => f && f.gid === ENTERED_QA_AT_FIELD_GID);
const dateMatches = existingDate && existingDate.date_value &&
                    existingDate.date_value.date_time === tMoveIso;
if (personMatches && dateMatches) { return []; }

return [{
  json: {
    taskGid: task.gid, taskName: task.name,
    assigneeGid: preMoveAssignee.gid, assigneeName: preMoveAssignee.name,
    qaCameFromFieldGid: QA_CAME_FROM_FIELD_GID,
    enteredQaAtFieldGid: ENTERED_QA_AT_FIELD_GID,
    tMoveIso,
    derivedFrom,
  }
}];

// v3.3: also drop gracefully when Get Task returned an Asana error body
// (404 from a deleted/inaccessible task, etc.). Without this guard, the error
// body would flow downstream, Get Stories would 404 too, and the run would
// fail loudly via the errorWorkflow Slack pager.
//
// We do NOT log here — the post-Filter forward already records the taskGid;
// inspection via n8n execution log shows the cause if we ever want to dig.
const QA_SECTION_GID = '1209047939293885';
const taskResp = $json;
// Asana 404 body shape: { errors: [{ message, help }] }, no .data, no .memberships
if (taskResp && Array.isArray(taskResp.errors)) { return []; }
const task = (taskResp && taskResp.data) ? taskResp.data : taskResp;
if (!task || !task.gid || !Array.isArray(task.memberships)) { return []; }
const inQA = task.memberships.some(m => m && m.section && m.section.gid === QA_SECTION_GID);
if (!inQA) { return []; }
const upstream = $('Filter: only QA section moves').first().json;
return [{ json: upstream }];
